/** The one alpha-test threshold of the trees: every level and pass (trees/Foliage.md#alpha). */
export const ALPHA_TEST = 0.5;

const atlases = new Map<FoliageKind, LeafAtlas>();

/**
 * Leaf atlas (alpha = leaf mask, grey = shading, the vertex colour tints it). Left half: one cluster (needle spray
 * along v / leaves splayed from the bottom centre); right half: a tileable dense patch of the same leaves at the same
 * size, repeated on the tiled (merged / crown) cards.
 */
export function leafAtlas(kind: FoliageKind): LeafAtlas {
  const cached = atlases.get(kind);
  if (cached) return cached;
  const S = 128;
  const W = S * 2;
  const alpha = new Float32Array(W * S);
  const shade = new Float32Array(W * S).fill(1);
  /** While true, stamps wrap around the S x S tile (the dense patch repeats on tiled cards). */
  let wrap = false;
  const stamp = (cx: number, cy: number, r: number, v: number, x0: number) => {
    const ya = Math.floor(cy - r);
    const yb = Math.ceil(cy + r);
    const xa = Math.floor(cx - r);
    const xb = Math.ceil(cx + r);
    for (let yy = wrap ? ya : Math.max(0, ya); yy <= (wrap ? yb : Math.min(S - 1, yb)); yy++)
      for (let xx = wrap ? xa : Math.max(0, xa); xx <= (wrap ? xb : Math.min(S - 1, xb)); xx++) {
        const d = Math.sqrt((xx - cx) ** 2 + (yy - cy) ** 2);
        const a = Math.min(1, Math.max(0, r - d + 0.5));
        const x = ((xx % S) + S) % S;
        const y = ((yy % S) + S) % S;
        const k = y * W + x0 + x;
        if (a > alpha[k]) {
          alpha[k] = a;
          shade[k] = v;
        }
      }
  };
  const line = (x0: number, y0: number, x1: number, y1: number, r: number, v0: number, v1: number, ox: number) => {
    const n = Math.ceil(Math.sqrt((x1 - x0) ** 2 + (y1 - y0) ** 2) / 0.5);
    for (let i = 0; i <= n; i++) {
      const f = i / n;
      stamp(x0 + (x1 - x0) * f, y0 + (y1 - y0) * f, r, v0 + (v1 - v0) * f, ox);
    }
  };
  const leaf = (cx: number, cy: number, ang: number, l: number, wd: number, v: number, ox: number) => {
    // An ellipse along `ang` from (cx, cy), lighter at the tip, with a darker midrib.
    const dx = tcos(ang);
    const dy = tsin(ang);
    const n = Math.ceil(l / 0.7);
    for (let i = 0; i <= n; i++) {
      const f = i / n;
      const r = wd * tsin(Math.PI * Math.min(1, f * 1.05 + 0.02));
      stamp(cx + dx * l * f, cy + dy * l * f, Math.max(0.6, r), v * (0.85 + 0.25 * f), ox);
    }
    line(cx, cy, cx + dx * l * 0.9, cy + dy * l * 0.9, 0.5, v * 0.7, v * 0.8, ox);
  };
  const blob = (ox: number, seed: number) => {
    // The dense, tileable leaf patch of the tiled cards: the same leaves / needles, at the same size in px, as the
    // cluster half, so a merged card shows the same foliage at the same texel density (trees/Lod.md#levels).
    wrap = true;
    const r = (k: number) => unit(mix32(seed, k));
    if (kind === 'needles')
      for (let i = 0; i < 16; i++) {
        const cx = r(i * 5) * S;
        const cy = r(i * 5 + 1) * S;
        const ang = r(i * 5 + 2) * Math.PI * 2;
        const len = 64 + 20 * r(i * 5 + 3);
        const dx = tcos(ang);
        const dy = tsin(ang);
        line(cx, cy, cx + dx * len, cy + dy * len, 1.2, 0.5, 0.6, ox);
        for (let n = 0; n * 4.6 < len; n++) {
          const f = (n * 4.6) / len;
          for (const side of [-1, 1]) {
            const a = ang + side * (0.85 + 0.25 * r(i * 97 + n * 2 + (side > 0 ? 1 : 0)));
            const l = 40 * (1 - f * 0.45) * 0.8;
            const px = cx + dx * len * f;
            const py = cy + dy * len * f;
            line(px, py, px + tcos(a) * l, py + tsin(a) * l, 0.75, 0.6, 1.08, ox);
          }
        }
      }
    else
      for (let i = 0; i < 110; i++) {
        const cx = r(i * 5) * S;
        const cy = r(i * 5 + 1) * S;
        const ang = r(i * 5 + 2) * Math.PI * 2;
        if (i % 6 === 0) line(cx, cy, cx + tcos(ang) * 30, cy + tsin(ang) * 30, 0.8, 0.5, 0.55, ox);
        leaf(cx, cy, ang, 20 + 8 * r(i * 5 + 3), 6.5, 0.75 + 0.35 * r(i * 5 + 4), ox);
      }
    wrap = false;
  };
  if (kind === 'needles') {
    // Spray along v (the card runs along the twig, tip at v = 1).
    line(S / 2, 2, S / 2, S - 4, 1.4, 0.5, 0.6, 0);
    for (let i = 0; i < 26; i++) {
      const y = 6 + i * 4.6;
      for (const side of [-1, 1]) {
        const a = Math.PI / 2 + side * (0.85 + 0.25 * unit(mix32(7, i * 2 + side)));
        const l = 40 * (1 - (i / 26) * 0.45);
        line(S / 2, y, S / 2 + tcos(a) * l, y + tsin(a) * l, 0.75, 0.6, 1.08, 0);
      }
    }
  } else {
    // Short twigs splayed from the bottom centre (the twig tip), each with small leaves along it and at its end.
    for (let t = 0; t < 4; t++) {
      const ta = Math.PI / 2 + (t - 1.5) * 0.42;
      const tl = 70 + 30 * unit(mix32(4, t));
      const ex = S / 2 + tcos(ta) * tl;
      const ey = 4 + tsin(ta) * tl;
      line(S / 2, 4, ex, ey, 0.8, 0.5, 0.55, 0);
      for (let i = 0; i < 6; i++) {
        const f = 0.3 + i * 0.13;
        const side = i % 2 ? 1 : -1;
        const a = ta + side * (0.7 + 0.3 * unit(mix32(5, t * 8 + i)));
        const l = 20 + 8 * unit(mix32(6, t * 8 + i));
        leaf(S / 2 + (ex - S / 2) * f, 4 + (ey - 4) * f, a, l, 6.5, 0.75 + 0.35 * unit(mix32(9, t * 8 + i)), 0);
      }
      leaf(ex, ey, ta, 24, 7, 0.95, 0);
    }
  }
  blob(S, kind === 'needles' ? 31 : 41);
  const data = new Uint8Array(W * S * 4);
  for (let k = 0; k < W * S; k++) {
    const c = Math.round(Math.min(1, shade[k]) * 255);
    data.set([c, c, c, Math.round(alpha[k] * 255)], k * 4);
  }
  const atlas = { data, width: W, height: S };
  atlases.set(kind, atlas);
  return atlas;
}

/** Cluster card outline: polygon vertices (CCW) in card coordinates, (0..1)^2. */
export type Outline = [number, number][];

const outlines = new Map<FoliageKind, Outline>();

/**
 * The tight outline of a cluster card (trees/Performance.md#mitigations): an 8-direction bounding polygon (axis and
 * diagonal extents) of the texels of the cluster half of the atlas that pass ALPHA_TEST, grown by a texel. 6 to 8
 * vertices (coincident corners merge), so few pixels are spent on texels the alpha test throws away.
 */
export function clusterOutline(kind: FoliageKind): Outline {
  const cached = outlines.get(kind);
  if (cached) return cached;
  const { data, width, height } = leafAtlas(kind);
  const S = height;
  const thr = ALPHA_TEST * 255;
  let [x0, x1, y0, y1, s0, s1, d0, d1] = [Infinity, -Infinity, Infinity, -Infinity, Infinity, -Infinity, Infinity, -Infinity];
  for (let y = 0; y < S; y++)
    for (let x = 0; x < S; x++) {
      if (data[(y * width + x) * 4 + 3] < thr) continue;
      // Texel corners in card units.
      for (const [cx, cy] of [
        [x, y],
        [x + 1, y],
        [x, y + 1],
        [x + 1, y + 1],
      ]) {
        const u = cx / S;
        const v = cy / S;
        x0 = Math.min(x0, u);
        x1 = Math.max(x1, u);
        y0 = Math.min(y0, v);
        y1 = Math.max(y1, v);
        s0 = Math.min(s0, u + v);
        s1 = Math.max(s1, u + v);
        d0 = Math.min(d0, u - v);
        d1 = Math.max(d1, u - v);
      }
    }
  const m = 1 / S;
  [x0, y0, s0, d0] = [x0 - m, y0 - m, s0 - m, d0 - m];
  [x1, y1, s1, d1] = [x1 + m, y1 + m, s1 + m, d1 + m];
  const clamp = (p: [number, number]): [number, number] => [
    Math.min(1, Math.max(0, p[0])),
    Math.min(1, Math.max(0, p[1])),
  ];
  const raw: [number, number][] = [
    [s0 - y0, y0],
    [d1 + y0, y0],
    [x1, x1 - d1],
    [x1, s1 - x1],
    [s1 - y1, y1],
    [d0 + y1, y1],
    [x0, x0 - d0],
    [x0, s0 - x0],
  ].map((p) => clamp(p as [number, number]));
  const out: Outline = [];
  for (const p of raw) {
    const q = out[out.length - 1];
    if (!q || Math.abs(q[0] - p[0]) > 1e-6 || Math.abs(q[1] - p[1]) > 1e-6) out.push(p);
  }
  if (out.length > 1 && Math.abs(out[0][0] - out[out.length - 1][0]) < 1e-6 && Math.abs(out[0][1] - out[out.length - 1][1]) < 1e-6)
    out.pop();
  outlines.set(kind, out);
  return out;
}

/** Tiled card outline: the octagon around the ellipse the tiled leaves fade to (trees/materials.ts). */
export const TILED_OUTLINE: Outline = [
  [0.293, 0],
  [0.707, 0],
  [1, 0.293],
  [1, 0.707],
  [0.707, 1],
  [0.293, 1],
  [0, 0.707],
  [0, 0.293],
];

