/** LOD budget (spec: trees/Lod.md#budget): per species, with these defaults. */
export interface LodSettings {
  /**
   * Level i -> i + 1 when the tree's bounding sphere covers less than this share of the screen height: LOD0->1,
   * LOD1->2, LOD2->impostor. Scaled by the graphics quality setting.
   */
  thresholds: [number, number, number];
  /** Back to the finer level only above threshold x (1 + hysteresis). */
  hysteresis: number;
  /** Cross-fade time (s). */
  fadeTime: number;
}

/** 6 %, 2.5 %, 1 % of the screen height: a 15 m tree at a 60 deg field of view changes at ~215, 520 and 1300 m. */
export const DEFAULT_LOD: LodSettings = {
  thresholds: [0.06, 0.025, 0.01],
  hysteresis: 0.15,
  fadeTime: 0.3,
};

/**
 * Trees closer than this (m) are always LOD0, whatever their screen height, the field of view or the quality
 * setting (trees/Lod.md#selection): a player near a tree only ever sees it at full detail.
 */
export const FULL_DETAIL_DISTANCE = 120;

export type BarkTexture = 'furrowed' | 'smooth';
export type FoliageKind = 'needles' | 'broadleaf';

export interface SpeciesDef {
  name: string;
  axiom: string;
  rules: RuleDef[];
  constants?: Record<string, number>;
  iterations: number;
  /** Rewriting stops before the string would hold more F segments than this. */
  segmentCap: number;
  /** Turn angle of + - & ^ < > without an explicit angle (deg). */
  angle: number;
  lengthScale: number;
  /** Radius at the base (m) and the factor `!` multiplies it by. */
  baseRadius: number;
  radiusDecay: number;
  /** Heading bends towards this vector after every segment, by `tropismStrength`. */
  tropism: [number, number, number];
  tropismStrength: number;
  bark: { color: string; texture: BarkTexture; /** repeats per metre of branch */ tiling: number };
  foliage: {
    kind: FoliageKind;
    /** Leaf card size (m) and cards per cluster. */
    cardSize: number;
    density: number;
    palette: string[];
  };
  lod?: Partial<LodSettings>;
  /** Instance scale range. */
  scale: [number, number];
  /** Branches thinner than this (m) are plain cards inside the foliage, not tubes (trees/Performance.md#mitigations). */
  twigRadius: number;
  /** Most LOD0 triangles a variant may have (12,000; shrubs 4,000). */
  maxTriangles: number;
  /** Trunk / first-order limb segments at least this thick (m) collide (trees/Placement.md#collision). */
  collisionRadius: number;
  /** Pre-generated variants (default 8). */
  variants?: number;
}

export const CONIFER: SpeciesDef = {
  name: 'Conifer',
  // A straight leader A adds an internode and a whorl of five limbs per iteration; the limb apices B fork into
  // flat twig sprays (the needle clusters sit on the twigs) and droop under the gravity tropism, so the oldest
  // (lowest) whorls are the longest.
69:    cardSize: number;
70:    density: number;
77:  twigRadius: number;
79:  maxTriangles: number;
120:    kind: 'needles',
121:    cardSize: 0.85,
122:    density: 2,
126:  twigRadius: 0.03,
127:  maxTriangles: 12000,
181:    kind: 'broadleaf',
182:    cardSize: 1.2,
183:    density: 3,
187:  twigRadius: 0.03,
188:  maxTriangles: 12000,
227:    kind: 'broadleaf',
228:    cardSize: 0.55,
229:    density: 3,
