p='species.ts'
s=open(p).read()
def rep(o,n,c=1):
    global s
    assert s.count(o)==c,(o[:80],s.count(o))
    s=s.replace(o,n)
rep("""  /**
   * Level i -> i + 1 when the tree's bounding sphere covers less than this share of the screen height: LOD0->1,
   * LOD1->2, LOD2->impostor. Scaled by the graphics quality setting.
   */
  thresholds: [number, number, number];""","""  /**
   * Shares of the screen height the tree's bounding sphere covers (scaled by the graphics quality setting): below
   * [0] its sprites start thinning (trees/Foliage.md#simplification), below [1] the branches go LOD0 -> LOD1, below
   * [2] the tree becomes the impostor (LOD2).
   */
  thresholds: [number, number, number];""")
rep("""/** 6 %, 2.5 %, 1 % of the screen height: a 15 m tree at a 60 deg field of view changes at ~215, 520 and 1300 m. */""","""/** 6 %, 2.5 %, 1 % of the screen height: for a 15 m tree at a 60 deg field of view ~215, 520 and 1300 m. */""")
rep(""" * Trees closer than this (m) are always LOD0, whatever their screen height, the field of view or the quality
 * setting (trees/Lod.md#selection): a player near a tree only ever sees it at full detail.""",""" * Trees closer than this (m) are always LOD0 with every sprite at full size, whatever their screen height, the field
 * of view or the quality setting (trees/Lod.md#selection): a player near a tree only ever sees it at full detail.""")
rep("""  foliage: {
    kind: FoliageKind;
    /** Leaf card size (m) and cards per cluster. */
    cardSize: number;
    density: number;
    palette: string[];
  };""","""  foliage: {
    /** Which cluster sprite atlas (trees/leaftex.ts): needle sprays or leaf bunches. */
    kind: FoliageKind;
    /** Sprite size (m) at a leaf point, before the cluster-size variation. */
    spriteSize: number;
    /** Leaves (or sprays) per cluster image of the atlas, relative to the default. */
    density: number;
    palette: string[];
  };""")
rep("""  /** Branches thinner than this (m) are plain cards inside the foliage, not tubes (trees/Performance.md#mitigations). */
  twigRadius: number;
  /** Most LOD0 triangles a variant may have (12,000; shrubs 4,000). */
  maxTriangles: number;""","""  /** Branches thinner than this (m) are left out: the foliage sprites cover them (trees/Lod.md#levels). */
  twigRadius: number;
  /** Most LOD0 branch triangles (6,000; shrubs 2,000) and sprites per crown (600; shrubs 200). */
  maxBranchTriangles: number;
  maxSprites: number;""")
for old,new in [("""    kind: 'needles',
    cardSize: 0.85,
    density: 2,""","""    kind: 'needles',
    spriteSize: 1.3,
    density: 1,"""),("""    kind: 'broadleaf',
    cardSize: 1.2,
    density: 3,""","""    kind: 'broadleaf',
    spriteSize: 1.7,
    density: 1,"""),("""    kind: 'broadleaf',
    cardSize: 0.55,
    density: 3,""","""    kind: 'broadleaf',
    spriteSize: 0.85,
    density: 1.2,""")]:
    rep(old,new)
rep("""  twigRadius: 0.03,
  maxTriangles: 12000,""","""  twigRadius: 0.03,
  maxBranchTriangles: 6000,
  maxSprites: 600,""",2)
rep("""  twigRadius: 0.015,
  maxTriangles: 4000,""","""  twigRadius: 0.015,
  maxBranchTriangles: 2000,
  maxSprites: 200,""")
open(p,'w').write(s)
EOF
echo ok

