  let r = 0;
  for (let i = 0; i < p0.length; i += 3)
    r = Math.max(r, Math.sqrt(p0[i] ** 2 + (p0[i + 1] - cy) ** 2 + p0[i + 2] ** 2));
  for (let i = 0; i < sp.position.length / 3; i++) {
    const [x, y, z] = [sp.position[i * 3], sp.position[i * 3 + 1] - cy, sp.position[i * 3 + 2]];
    r = Math.max(r, Math.sqrt(x * x + y * y + z * z) + sp.sprite[i * 4 + 2] * 0.71);
  }

