		// Trunk bend + limb sway (phase per limb, more for higher orders and further out). Sprites: at their centre.
		float tBranch = 0.012 * tGust * ( 1.0 + 0.35 * treeWind.x ) * treeWind.z * sin( wsTime * 1.7 + treeWind.y + treeInst.z );
