// --- materials -------------------------------------------------------------------------------------------------

const materials = new Map<string, MeshStandardMaterial | MeshBasicMaterial | MeshDepthMaterial>();
let foliageA2C = false;

/** Alpha-to-coverage on the sprites when the renderer has MSAA (engine/materials.ts `setFoliageAntialias`). */
export function setTreeFoliageAntialias(on: boolean): void {
  foliageA2C = on;
  for (const [k, m] of materials)
    if (k.startsWith('sprite:') && m.alphaToCoverage !== on) {
      m.alphaToCoverage = on;
      m.needsUpdate = true;
    }
}

export function barkMaterial(kind: BarkTexture): MeshStandardMaterial {
  const key = `bark:${kind}`;
  let m = materials.get(key) as MeshStandardMaterial | undefined;
  if (m) return m;
  m = new MeshStandardMaterial({ vertexColors: true, map: barkTexture(kind), roughness: 0.95 });
  m.name = `tree ${key}`;
  m.defines = { TREE_FULL: FULL_DETAIL_DISTANCE.toFixed(1) };
  hookStandard(m, 'tree-bark-v4', false);
  materials.set(key, m);
  return m;
}

/** How far the atlas normal map bends the crown normal. */
const SPRITE_BEND = 0.8;

/**
 * The lit foliage sprites (trees/Foliage.md#shading). They draw after the sprite depth prepass
 * (`spritePrepassMaterial`) with a less-or-equal depth test: the prepass writes each covered pixel's nearest sprite
 * depth (pushed back a hair by a polygon offset), so only that sprite shades it (trees/Performance.md#mitigations)
 * and a last-bit depth difference between the two programs can never make a sprite fail its own depth.
 */
export function spriteMaterial(kind: FoliageKind, density: number): MeshStandardMaterial {
  const key = `sprite:lit:${kind}:${density}`;
  let m = materials.get(key) as MeshStandardMaterial | undefined;
  if (m) return m;
  const tex = spriteTextures(kind, density);
  m = new MeshStandardMaterial({
    vertexColors: true,
    map: tex.albedo,
    alphaTest: ALPHA_TEST,
    side: DoubleSide,
    roughness: 0.85,
  });
  m.name = `tree ${key}`;
  m.alphaToCoverage = foliageA2C;
  m.depthFunc = LessEqualDepth;
  m.depthWrite = false;
  m.defines = {
    TREE_SPRITE: 1,
    TREE_SKY: 1,
    TREE_FULL: FULL_DETAIL_DISTANCE.toFixed(1),
    TREE_BEND: SPRITE_BEND.toFixed(2),
    FALLBACK_AMBIENT: FALLBACK_AMBIENT.toFixed(2),
    RALLY_FOLIAGE: 0.45,
  };
  hookStandard(m, 'tree-sprite-v1', true, { tlSprNormal: { value: tex.normal } });
  materials.set(key, m);
  return m;
}

/** Sprite depth prepass: the same sprite positions, dither and alpha test, depth only, unlit fragment shader. */
export function spritePrepassMaterial(kind: FoliageKind, density: number): MeshBasicMaterial {
  const key = `sprite:prepass:${kind}:${density}`;
  let m = materials.get(key) as MeshBasicMaterial | undefined;
  if (m) return m;
  m = new MeshBasicMaterial({
    map: spriteTextures(kind, density).albedo,
    alphaTest: ALPHA_TEST,
    side: DoubleSide,
    colorWrite: false,
    polygonOffset: true,
    polygonOffsetFactor: 1,
    polygonOffsetUnits: 1,
  });
  m.name = `tree ${key}`;
  m.alphaToCoverage = foliageA2C;
  m.defines = { TREE_SPRITE: 1, TREE_FULL: FULL_DETAIL_DISTANCE.toFixed(1) };
  m.onBeforeCompile = (shader) => {
    addWorldUniforms(shader);
    Object.assign(shader.uniforms, treeUniforms);
    injectVertex(shader, true, true);
    injectFragment(shader);
  };
  m.customProgramCacheKey = () => 'tree-sprite-prepass-v1';
  materials.set(key, m);
  return m;
}

/**
 * Shadow-pass material: the same positions (wind, sprite facing + thinning), the caster flag (no dither) and, for
 * sprites, the material's map and ALPHA_TEST, which three copies over.
 */
export function treeDepthMaterial(sprite: boolean): MeshDepthMaterial {
  const key = `depth:${sprite}`;
  let m = materials.get(key) as MeshDepthMaterial | undefined;
  if (m) return m;
  m = new MeshDepthMaterial({ depthPacking: RGBADepthPacking });
  m.defines = { TREE_SHADOW_PASS: 1, TREE_FULL: FULL_DETAIL_DISTANCE.toFixed(1), ...(sprite ? { TREE_SPRITE: 1 } : {}) };
  m.onBeforeCompile = (shader) => {
    addWorldUniforms(shader);
    Object.assign(shader.uniforms, treeUniforms);
    injectVertex(shader, true, sprite);
    injectFragment(shader);
  };
  m.customProgramCacheKey = () => `tree-depth-v3-${sprite}`;
  materials.set(key, m);
  return m;
}

// --- impostor --------------------------------------------------------------------------------------------------

