varying vec2 vUv;
varying vec3 vN;
varying vec3 vR;
varying vec3 vU;
varying float vDepth;
varying float vAO;
void main() {
	vColor = color;
	vUv = uv;
	vN = normal;
	vR = vec3( 0.0 );
	vU = vec3( 0.0 );
	vAO = treeWind.w;
