 * Stage 4, impostor baking (spec: trees/Lod.md#levels): LOD0 rendered from N x N directions over the upper
 * hemisphere (hemi-octahedral grid, frame (i, j) looks from `hemiOctDecode(i / (N-1), j / (N-1))`) into two
 * atlases: albedo (sRGB) + coverage, and object-space normal + depth along the view (0.5 = the bounding sphere
 * centre). Both are premultiplied by coverage (empty texels are 0), so frame blending and mipmaps never pull in a
 * background colour; the impostor shader divides by the blended coverage (trees/materials.ts). Lit at runtime by
 * the same sun as the geometry.
 */

/** Pixels per frame (the impostor only draws trees a few dozen px tall). */
export const IMPOSTOR_FRAME_PX = 48;

export interface ImpostorPixels {
  size: number;
  albedo: Uint8Array;
  normal: Uint8Array;
}

const VERT = /* glsl */ `
attribute vec4 treeWind;
uniform vec3 uCenter;
uniform vec3 uDir;
uniform float uR;
varying vec3 vColor;
varying vec2 vUv;
varying vec3 vN;
varying float vDepth;
varying float vAO;
void main() {
	vColor = color;
	vUv = uv;
	vN = normal;
	vAO = treeWind.w;
	vDepth = 0.5 + 0.5 * dot( position - uCenter, uDir ) / uR;
	gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );
}`;

const FRAG = /* glsl */ `
uniform sampler2D uMap;
uniform float uAlphaTest;
uniform int uMode;
varying vec3 vColor;
varying vec2 vUv;
varying vec3 vN;
varying float vDepth;
varying float vAO;
vec3 toSRGB( vec3 c ) {
	return mix( c * 12.92, 1.055 * pow( c, vec3( 1.0 / 2.4 ) ) - 0.055, step( vec3( 0.0031308 ), c ) );
}
void main() {
	vec4 t = texture2D( uMap, vUv );
	if ( t.a < uAlphaTest ) discard;
	if ( uMode == 0 ) gl_FragColor = vec4( toSRGB( vColor * t.rgb * mix( 0.65, 1.0, vAO ) ), 1.0 );
	else gl_FragColor = vec4( normalize( vN ) * 0.5 + 0.5, clamp( vDepth, 0.0, 1.0 ) );
}`;

const shared = {
  uCenter: { value: new Vector3() },
  uDir: { value: new Vector3() },
  uR: { value: 1 },
  uMode: { value: 0 },
};

function bakeMaterial(map: Texture, leaf: boolean): ShaderMaterial {
  return new ShaderMaterial({
    vertexShader: VERT,
    fragmentShader: FRAG,
    vertexColors: true,
    side: leaf ? DoubleSide : FrontSide,
    uniforms: { ...shared, uMap: { value: map }, uAlphaTest: { value: leaf ? ALPHA_TEST : 0 } },
  });
}

export function bakeImpostor(
  renderer: WebGLRenderer,
  parts: { geometry: BufferGeometry; map: Texture; leaf: boolean }[],
  sphere: { cy: number; r: number },
): ImpostorPixels {
  const N = IMPOSTOR_FRAMES;
  const F = IMPOSTOR_FRAME_PX;
  const size = N * F;
  const scene = new Scene();
  const mats = parts.map((p) => bakeMaterial(p.map, p.leaf));
  parts.forEach((p, i) => scene.add(new Mesh(p.geometry, mats[i])));
  const R = sphere.r;
  const center = new Vector3(0, sphere.cy, 0);
  const cam = new OrthographicCamera(-R, R, R, -R, R * 0.01, R * 4);
  const rt = new WebGLRenderTarget(size, size);
  const prevTarget = renderer.getRenderTarget();
  const prevColor = renderer.getClearColor(new Color());
  const prevAlpha = renderer.getClearAlpha();
  const prevAutoClear = renderer.autoClear;
  const prevShadow = renderer.shadowMap.autoUpdate;
  renderer.shadowMap.autoUpdate = false;
  renderer.autoClear = false;
  renderer.setClearColor(0x000000, 0);
  const out: Uint8Array[] = [];
  shared.uCenter.value.copy(center);
  shared.uR.value = R;
  for (let mode = 0; mode < 2; mode++) {
    shared.uMode.value = mode;
    rt.scissorTest = false;
    rt.viewport.set(0, 0, size, size);
    renderer.setRenderTarget(rt);
    renderer.clear(true, true, false);
    for (let j = 0; j < N; j++)
      for (let i = 0; i < N; i++) {
        const d = hemiOctDecode(i / (N - 1), j / (N - 1));
        shared.uDir.value.set(...d);
        cam.position.copy(center).addScaledVector(shared.uDir.value, R * 2);
        // Upright like the impostor billboard; looking straight down, +X stays the frame's right.
        cam.up.set(...((d[1] > 0.999 ? [0, 0, -1] : [0, 1, 0]) as [number, number, number]));
        cam.lookAt(center);
        cam.updateMatrixWorld();
        rt.viewport.set(i * F, j * F, F, F);
        rt.scissor.set(i * F, j * F, F, F);
        rt.scissorTest = true;
        renderer.setRenderTarget(rt);
        renderer.clearDepth();
        renderer.render(scene, cam);
      }
    const px = new Uint8Array(size * size * 4);
    renderer.readRenderTargetPixels(rt, 0, 0, size, size, px);
    out.push(px);
  }
  renderer.setRenderTarget(prevTarget);
  renderer.setClearColor(prevColor, prevAlpha);
  renderer.autoClear = prevAutoClear;
  renderer.shadowMap.autoUpdate = prevShadow;
  rt.dispose();
  for (const m of mats) m.dispose();
  return { size, albedo: out[0], normal: out[1] };
}

/**
 * Every variant's impostor in ONE texture array (trees/Performance.md#mitigations: all impostors draw in a single
 * call): layer 2i = variant i's albedo + coverage, 2i + 1 = its normal + depth, both premultiplied by coverage. The
 * albedo stays sRGB-encoded (one array has one colour space; the shader decodes it). Mip levels are the
 * coverage-preserving chain (trees/Foliage.md#alpha), written into the array after three allocates it (three
 * uploads only level 0 of an array texture itself).
 */
export function impostorArray(renderer: WebGLRenderer, pixels: ImpostorPixels[]): DataArrayTexture {
  const size = pixels[0].size;
  const layer = size * size * 4;
  const data = new Uint8Array(layer * pixels.length * 2);
  const chains = pixels.map((px, i) => {
    data.set(px.albedo, layer * 2 * i);
    data.set(px.normal, layer * (2 * i + 1));
    return coverageMips(px.albedo, size, size, true, px.normal);
  });
  const t = new DataArrayTexture(data, size, size, pixels.length * 2);
  t.magFilter = LinearFilter;
  t.minFilter = LinearMipmapLinearFilter;
  t.generateMipmaps = true;
  t.needsUpdate = true;
  renderer.initTexture(t);
  const gl = renderer.getContext() as WebGL2RenderingContext;
  const handle = (renderer.properties.get(t) as { __webglTexture?: WebGLTexture }).__webglTexture;
  if (handle) {
    gl.bindTexture(gl.TEXTURE_2D_ARRAY, handle);
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
    chains.forEach((c, i) => {
      for (let level = 1; level < c.main.length; level++) {
        const a = c.main[level];
        const n = c.companion[level];
        gl.texSubImage3D(gl.TEXTURE_2D_ARRAY, level, 0, 0, 2 * i, a.width, a.height, 1, gl.RGBA, gl.UNSIGNED_BYTE, a.data);
        gl.texSubImage3D(gl.TEXTURE_2D_ARRAY, level, 0, 0, 2 * i + 1, n.width, n.height, 1, gl.RGBA, gl.UNSIGNED_BYTE, n.data);
      }
    });
    gl.bindTexture(gl.TEXTURE_2D_ARRAY, null);
    renderer.resetState();
  }
  return t;
}

