import { describe, expect, test } from '@rstest/core';
import { checkBudget, summarize } from '../../src/games/rally/game/tree-bench';
import { derive } from '../../src/games/rally/trees/grammar';
import {
  hashText,
  tcos,
  tsin,
  TreeRng,
} from '../../src/games/rally/trees/math';
import {
  MAX_FADES,
  selectLevel,
  stepFade,
  type FadeState,
} from '../../src/games/rally/trees/draw';
import { clusterOutline } from '../../src/games/rally/trees/leaftex';
import { pruneHalf } from '../../src/games/rally/trees/mesh';
import { placeTree, treeColliders } from '../../src/games/rally/trees/placement';
import { buildSkeleton } from '../../src/games/rally/trees/skeleton';
import {
  SPECIES,
  TREE_TYPES,
  getSpecies,
  speciesHash,
  type SpeciesDef,
} from '../../src/games/rally/trees/species';
import {
  generateVariant,
  variantSeed,
} from '../../src/games/rally/trees/variants';

/** Procedural L-system trees: the pure stages (grammar, skeleton, meshing, placement) run in node. */
describe('trees', () => {
  test('the PRNG and trig are fixed integer / polynomial code', () => {
    const r = new TreeRng(12345);
    expect([r.u32(), r.u32(), r.u32()]).toEqual([
      new TreeRng(12345).u32(),
      (() => {
        const q = new TreeRng(12345);
        q.u32();
      // A kept segment's parent is kept: LOD1 is a connected part of LOD0.
      sk.segments.forEach((s, i) => {
        if (keep[i] && s.parent >= 0) expect(keep[s.parent]).toBe(1);
      });
      const { meshes } = generateVariant(def, 3);
      const tris = meshes.levels.map(
        (l) => (l.bark.index.length + l.foliage.index.length) / 3,
      );
      console.log(
        `${def.name}: ${sk.segments.length} segments, ${sk.leaves.length} leaves, ` +
          `tris ${tris.join(' / ')}, height ${meshes.height.toFixed(1)} m, radius ${meshes.radius.toFixed(1)} m`,
      );
      expect(meshes.levels[1].segments).toBe(Math.ceil(sk.segments.length / 2));
      expect(meshes.levels[2].segments).toBeLessThanOrEqual(
        meshes.levels[1].segments,
      );
      expect(tris[1]).toBeLessThan(tris[0]);
      expect(tris[2]).toBeLessThan(tris[1]);
    },
  );

  test('a species change gives new variant seeds', () => {
    const def = getSpecies('Conifer');
    const changed = { ...def, angle: def.angle + 1 };
    expect(speciesHash(changed)).not.toBe(speciesHash(def));
    expect(variantSeed(changed, 0)).not.toBe(variantSeed(def, 0));
  });

  test('every tree type maps to a species', () => {
    for (const s of Object.values(TREE_TYPES)) expect(getSpecies(s)).toBeTruthy();
